/**
 * TEMPORARY type safeguards for the 2.4.1 type changes (autogenerated by
 * Qwen4 during code review of PR #69). These are compile-time checks, not
 * behaviour tests: the fixtures are shape-faithful captures of real API
 * payloads and fail compilation if the types drift from them. They do not
 * follow the repo's operations/mocks testing pattern and are suitable for
 * removal once the types have settled after release.
 */
describe('FormContentType / Component / EntrySys types', () => {
    it('accepts a real form content type payload', () => {
        const form = {
            id: 'contactForm',
            name: { 'en-GB': 'Contact Form' },
            description: { 'en-GB': 'Get in touch' },
            enabled: true,
            dataFormat: 'form',
            defaultLanguage: 'en-GB',
            supportedLanguages: ['en-GB'],
            entryTitleField: 'createdAt',
            projectId: 'myProject',
            uuid: '0f6c0a1e-0000-4000-8000-000000000001',
            includeInDelivery: false,
            workflowId: 'contensisFormBasic',
            versionHistory: { enabled: true },
            reviews: {
                onDemand: { enabled: false },
                schedule: { enabled: false, intervalDays: 180, windowDays: 30 },
            },
            groups: [{ id: 'default', name: { 'en-GB': 'Default' } }],
            fields: [
                {
                    id: 'fullName',
                    name: { 'en-GB': 'Full name' },
                    dataType: 'string',
                    validations: { required: { message: { 'en-GB': 'Enter your name' } } },
                    editor: {
                        id: 'text',
                        label: { 'en-GB': 'Short text' },
                        instructions: { 'en-GB': 'First and last name' },
                        properties: { placeholderText: { 'en-GB': 'Enter your name' }, prefix: 'AF' },
                    },
                },
                {
                    id: 'age',
                    name: { 'en-GB': 'Age' },
                    dataType: 'integer',
                    validations: { min: { value: 18, message: { 'en-GB': 'Must be 18 or over' } } },
                    editor: { id: 'integer' },
                },
                {
                    id: 'when',
                    name: { 'en-GB': 'When' },
                    dataType: 'dateTime',
                    editor: { id: 'dateparts' },
                },
                {
                    id: 'topic',
                    name: { 'en-GB': 'Topic' },
                    dataType: 'string',
                    validations: {
                        allowedValues: {
                            message: null,
                            labeledValues: [{ value: 'sales', label: { 'en-GB': 'Sales' } }],
                        },
                    },
                    editor: { id: 'list-dropdown' },
                },
                {
                    id: 'website',
                    name: { 'en-GB': 'Website' },
                    dataType: 'string',
                    dataFormat: 'url',
                    editor: { id: 'url' },
                },
                {
                    id: 'interests',
                    name: { 'en-GB': 'Interests' },
                    dataType: 'stringArray',
                    editor: { id: 'list', properties: { repeatableItemDefault: {} } },
                },
            ],
            properties: {
                captcha: { enabled: false },
                localizations: {
                    closedReasonMessage: { 'en-GB': null },
                    disabledReasonMessage: null,
                    requirePermissionToPostMessage: { 'en-GB': 'Sign in to post' },
                },
                confirmationRules: [
                    {
                        return: {
                            content: {
                                'en-GB': [{ type: '_paragraph', id: 'd05a614b', value: 'Thank you' }],
                            },
                        },
                    },
                    {
                        when: { and: [{ field: 'fullName', equalTo: 'Neil' }] },
                        return: { link: { sys: { uri: { 'en-GB': '/thanks' } } } },
                    },
                    // "Redirect to site view location" variant (management UI option;
                    // shape not yet captured in a live payload)
                    { return: { link: { sys: { node: { id: 'thanks-page' } } } } },
                ],
                autoSaveProgress: true,
                requirePermissionToPost: false,
                autoCloseForm: true,
                autoCloseDateTime: '2026-07-09T23:00:00Z',
                context: { enabled: true },
            },
            version: {
                createdBy: 'user@example.com', created: '2026-01-01T09:00:00Z',
                modifiedBy: 'user@example.com', modified: '2026-01-02T09:00:00Z',
                publishedBy: 'user@example.com', published: '2026-01-03T09:00:00Z',
                versionNo: '1.0.0',
            },
        };
        expect(form.fields.length).toBe(6);
    });
    it('rejects canvas-only field shapes', () => {
        // @ts-expect-error 'object' is not a forms dataType
        const badDataType = { id: 'x', name: { 'en-GB': 'X' }, dataType: 'object' };
        const badValidation = {
            id: 'y', name: { 'en-GB': 'Y' }, dataType: 'string',
            // @ts-expect-error canvas-only validation key must not be accepted on a form field
            validations: { taxonomyRoot: { key: 'topics' } },
        };
        // @ts-expect-error unknown editor id must not be accepted
        const badEditor = { id: 'z', name: { 'en-GB': 'Z' }, dataType: 'string', editor: { id: 'richtext' } };
        expect(badDataType).toBeDefined();
        expect(badValidation).toBeDefined();
        expect(badEditor).toBeDefined();
    });
    it('accepts a real component payload incl. child-component flags', () => {
        const component = {
            id: 'header',
            name: { 'en-GB': 'Header' },
            dataFormat: 'component',
            fields: [],
            isChild: false,
            hasChildren: true,
            canAddChildComponents: true,
            canBeAddedAsChildComponent: false,
            version: {
                createdBy: 'user@example.com', created: '2026-01-01T09:00:00Z',
                modifiedBy: 'user@example.com', modified: '2026-01-02T09:00:00Z',
                publishedBy: 'user@example.com', published: '2026-01-03T09:00:00Z',
                versionNo: '2.3.1',
            },
        };
        // The management type must stay assignable to the core-api base type
        // (create/update payloads are typed with the base).
        const asBase = component;
        expect(asBase.dataFormat).toBe('component');
    });
    it('exposes the management Component through IComponentOperations', () => {
        // The interface, not just the concrete class, must surface the
        // child-component flags — this is what client.components is typed as.
        const ops = jasmine.createSpyObj('ops', ['get']);
        ops.get.and.returnValue(Promise.resolve({
            id: 'header', name: { 'en-GB': 'Header' }, dataFormat: 'component', isChild: true,
        }));
        return ops.get('header').then((component) => {
            expect(component.isChild).toBe(true);
        });
    });
    it('accepts a real entry sys payload', () => {
        const sys = {
            availableLanguages: ['en-GB'],
            contentTypeId: 'article',
            dataFormat: 'entry',
            id: '123',
            isPublished: true,
            language: 'en-GB',
            owner: 'user@example.com',
            metadata: { campaign: 'spring' },
            projectId: 'myProject',
            properties: {},
            review: {
                due: '2026-08-01T09:00:00Z',
                windowStart: '2026-07-25T09:00:00Z',
                created: '2026-07-01T09:00:00Z',
                type: 'scheduled',
                assigned: '2026-07-02T09:00:00Z',
                assignedBy: 'editor@example.com',
                assignedTo: 'reviewer@example.com',
            },
            schedules: { publish: { dateTime: '2026-08-01T09:00:00Z' } },
            slug: 'my-article',
            translationState: 'translated',
            unavailableLanguages: [],
            // uri intentionally absent — search/list results omit it
            version: {
                createdBy: 'user@example.com', created: '2026-01-01T09:00:00Z',
                modifiedBy: 'user@example.com', modified: '2026-01-02T09:00:00Z',
                publishedBy: 'user@example.com', published: '2026-01-03T09:00:00Z',
                versionNo: '1.2.3',
            },
            versionStatus: 'published',
            workflow: { status: 'Ready' },
        };
        const assetSlug = null; // assets carry a null slug
        // @ts-expect-error versionStatus is the core-api VersionStatus union
        const badStatus = 'archived';
        expect(sys.uri).toBeUndefined();
        expect(assetSlug).toBeNull();
        expect(badStatus).toBeDefined();
    });
});
export {};
